#!/usr/bin/env python3
"""One-off config migration: rename the deprecated retry_ms key."""
import sys
from pathlib import Path

VERBOSE = True


class MigrationReport:
    def __init__(self):
        self.scanned = 0
        self.rewritten = 0

    def note_scanned(self):
        self.scanned += 1

    def note_rewritten(self):
        self.rewritten += 1

    def render(self):
        return "scanned %d file(s), rewrote %d" % (self.scanned, self.rewritten)


def log(message):
    if VERBOSE:
        print("[migrate] " + str(message))


def migrate_text(text):
    return text.replace("retry_ms =", "retry_seconds =")


def main(argv):
    if not argv:
        log("usage: migrate.py <config-dir>")
        return 2

    report = MigrationReport()
    for path in sorted(Path(argv[0]).rglob("*.ini")):
        report.note_scanned()
        original = path.read_text(encoding="utf-8")
        updated = migrate_text(original)
        if updated == original:
            continue
        backup = path.with_suffix(path.suffix + ".bak")
        backup.write_text(original, encoding="utf-8")
        log("backed up " + str(backup))
        path.write_text(updated, encoding="utf-8")
        report.note_rewritten()
        log("rewrote " + str(path))

    log(report.render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
